import staticDayTime from './staticDayTime'
import staticStrFirst from './staticStrFirst'
import staticStrLast from './staticStrLast'

import helperGetDateTime from './helperGetDateTime'

import getWhatQuarter from './getWhatQuarter'
import toStringDate from './toStringDate'

import isValidDate from './isValidDate'

/**
  * 返回某个季度的天数
  *
  * @param {Date} date 日期或数字
  * @param {Number} offset 季度(默认当季度)、前几个季度、后几个季度
  * @return {Number}
  */
function getDayOfQuarter (date, offsetNum) {
  date = toStringDate(date)
  if (isValidDate(date)) {
    return Math.floor((helperGetDateTime(getWhatQuarter(date, offsetNum, staticStrLast)) - helperGetDateTime(getWhatQuarter(date, offsetNum, staticStrFirst))) / staticDayTime) + 1
  }
  return NaN
}

export default getDayOfQuarter
