import isArray from './isArray'
import lastArrayEach from './lastArrayEach'
import lastObjectEach from './lastObjectEach'
import lastMapEach from './lastMapEach'
import lastSetEach from './lastSetEach'
import isSet from './isSet'
import isMap from './isMap'

/**
  * 迭代器,从最后开始迭代
  *
  * @param {Object} obj 对象/数组
  * @param {Function} iterate(item, index, obj) 回调
  * @param {Object} context 上下文
  * @return {Object}
  */
function lastEach (obj, iterate, context) {
  if (obj) {
    if (isArray(obj)) {
      lastArrayEach(obj, iterate, context)
    } else if (isMap(obj)) {
      lastMapEach(obj, iterate, context)
    } else if (isSet(obj)) {
      lastSetEach(obj, iterate, context)
    } else {
      lastObjectEach(obj, iterate, context)
    }
  }
  return obj
}

export default lastEach
